function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const hdr = (($('GET header').first().json.values || [[]])[0] || []).map(s);
const cA = hdr.indexOf('next_action'), cP = hdr.indexOf('pause'), cN = hdr.indexOf('notes');
if (cA < 0 || cP < 0 || cN < 0) { throw new Error('ABORT: next_action/pause/notes column missing: ' + JSON.stringify(hdr)); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const LA = colLetter(cA), LP = colLetter(cP), LN = colLetter(cN);
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

// investor facts, merged across duplicate rows of the same name
const inv = {};
for (const r of invRaw) { const n = s(r.investor); if (!n) { continue; } const k = nz(n);
  if (!inv[k]) { inv[k] = { name: n, stage: false, email: false, dnc: false, contact: s(r.contact_person), emailText: '', rows: [] }; }
  const x = inv[k]; x.rows.push(r.row_number);
  if (s(r.stage)) { x.stage = true; } if (s(r.email)) { x.email = true; x.emailText = x.emailText || s(r.email); }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { x.dnc = true; } }

const A_STAGE = 'HOLD - fill investor stage in INVESTORS';
const A_EMAIL = 'HOLD - add investor email in INVESTORS';
const A_BOTH = 'HOLD - fill investor stage AND email in INVESTORS';
const A_NAME = 'HOLD - investor name not in INVESTORS (fix the name)';
const data = []; const counts = { stage: 0, email: 0, both: 0, name: 0, newly_paused_no_email: 0, already_marked: 0 };
const perInv = {};
function note(k, label) { if (!perInv[k]) { perInv[k] = { label: label, held: 0, startups: {} }; } return perInv[k]; }
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes') { continue; }               // never touch sent rows
  const paused = s(p.pause).toLowerCase() === 'yes';
  const notes = s(p.notes); const k = nz(p.investor); const x = inv[k];
  let action = null; let pauseNow = false; let addNote = '';
  if (paused && notes.indexOf('ON HOLD 2026-09-10 - investor stage missing') >= 0) {
    action = (x && !x.email && !s(p.email)) ? A_BOTH : A_STAGE;
  } else if (paused && notes.indexOf('investor name not found') >= 0) {
    action = A_NAME;
  } else if (!paused && !s(p.email)) {
    // queued with no address: it cannot send - hold it and say why
    action = (x && !x.stage) ? A_BOTH : A_EMAIL; pauseNow = true; addNote = 'ON HOLD 2026-09-11 - investor email missing';
  }
  if (!action) { continue; }
  if (s(p.next_action) === action && !pauseNow) { counts.already_marked++; continue; }
  if (!p.row_number) { throw new Error('ABORT: row without row_number'); }
  data.push({ range: 'PIPELINE!' + LA + p.row_number, values: [[action]] });
  if (pauseNow) { counts.newly_paused_no_email++;
    data.push({ range: 'PIPELINE!' + LP + p.row_number, values: [['Yes']] });
    data.push({ range: 'PIPELINE!' + LN + p.row_number, values: [[(notes ? notes + ' | ' : '') + addNote]] }); }
  if (action === A_STAGE) { counts.stage++; } else if (action === A_EMAIL) { counts.email++; } else if (action === A_BOTH) { counts.both++; } else { counts.name++; }
  const key = action === A_NAME ? ('name:' + s(p.investor)) : k;
  const e = note(key, action); e.held++; e.startups[s(p.startup)] = 1;
}
if (data.length > 3000) { throw new Error('ABORT: ' + data.length + ' cell writes exceeds guard'); }
if (!data.length) { throw new Error('NOTHING TO DO: every held row is already marked'); }

// the to-fill lists
const stageList = [], emailList = [], nameList = [];
for (const k of Object.keys(inv)) { const x = inv[k]; if (x.dnc) { continue; }
  const e = perInv[k]; const held = e ? e.held : 0; const sts = e ? Object.keys(e.startups).length : 0;
  if (!x.stage) { stageList.push([x.name, x.contact, x.emailText, x.email ? 'yes' : 'MISSING', held, sts, x.rows.join(',')]); }
  if (!x.email) { emailList.push([x.name, x.contact, x.stage ? 'yes' : 'MISSING', held, sts, x.rows.join(',')]); } }
for (const key of Object.keys(perInv)) { if (key.indexOf('name:') === 0) { nameList.push([key.slice(5), perInv[key].held, Object.keys(perInv[key].startups).join(', ')]); } }
stageList.sort(function (a, b) { return b[4] - a[4] || a[0].localeCompare(b[0]); });
emailList.sort(function (a, b) { return b[3] - a[3] || a[0].localeCompare(b[0]); });
nameList.sort(function (a, b) { return b[1] - a[1]; });
return [{ json: { columns: { next_action: LA, pause: LP, notes: LN }, counts: counts, cell_writes: data.length,
  stage_cols: ['investor', 'contact', 'email', 'has_email', 'deals_on_hold', 'startups_waiting', 'INVESTORS_rows'], stage_missing: stageList,
  email_cols: ['investor', 'contact', 'has_stage', 'deals_on_hold', 'startups_waiting', 'INVESTORS_rows'], email_missing: emailList,
  name_cols: ['investor_name_in_PIPELINE', 'deals_on_hold', 'startups'], name_not_found: nameList,
  data: data } }];
